import React from "react";
import "./Aplicacion.css";

const Aplicacion = React.memo(function Aplicacion(props) {
  return (
    <button
      type="button"
      className="mosaico-tile"
      onClick={(event) => props.onOpen(event.currentTarget)}
      aria-label={`Ver ${props.encabezado}`}
    >
      <img
        src={props.background}
        alt=""
        width="600"
        height="400"
        loading="lazy"
        decoding="async"
      />
      <span className="mosaico-info">
        <span className="mosaico-fecha">{props.fecha || "Sin fecha"}</span>
        <span className="mosaico-titulo">{props.encabezado}</span>
        <span className="mosaico-frase">{props.parrafo}</span>
      </span>
    </button>
  );
});

export default Aplicacion;
